562	impl AgentEvent {
563	    /// `true` for the four events that end a run: [`AgentEvent::RunCompleted`],
564	    /// [`AgentEvent::RunFailed`], [`AgentEvent::RunDeferred`] and
565	    /// [`AgentEvent::RunStopped`].
566	    ///
567	    /// This is the single definition of "terminal" every runner shares. A
568	    /// runner's cancel/timeout boundary loses to a terminal that already
569	    /// occurred; the `terminal_tests::classify` guard keeps a newly added
570	    /// variant from silently defaulting to non-terminal here.
571	    #[must_use]
572	    pub fn is_terminal(&self) -> bool {
573	        matches!(
574	            self,
575	            Self::RunCompleted { .. }
576	                | Self::RunFailed { .. }
577	                | Self::RunDeferred { .. }
578	                | Self::RunStopped { .. }
579	        )
580	    }
581	}
