585	/// Concatenate the text of all `Item::UserMessage` parts in the seed
586	/// conversation — the text input guardrails inspect.
587	fn user_text_of(conversation: &[crate::Item]) -> String {
588	    let mut s = String::new();
589	    for item in conversation {
590	        if let crate::Item::UserMessage { content } = item {
591	            for part in content {
592	                if let crate::ContentPart::Text { text } = part {
593	                    s.push_str(text);
594	                }
595	            }
596	        }
597	    }
598	    s
599	}
