601	/// The outcome of one tool call of a turn.
602	#[derive(Debug)]
603	enum ConcurrentOutcome {
604	    /// The call ran, failed, or was denied. Its result goes into the conversation.
605	    Done(crate::ToolCallOutcome),
606	    /// The call was deferred and did not run. Holds the raw effective args.
607	    Deferred(crate::PendingToolCall),
608	}
