610	/// Map one event of a handoff child run to the event that the parent
611	/// stream yields. Drops the child `RunStarted`. Adds `parent_usage` to the
612	/// usage of `RunCompleted`, `RunDeferred` and `RunStopped`, and records the
613	/// total on `run_span`. Passes every other event through.
614	fn reyield_child_event(
615	    ev: AgentEvent,
616	    parent_usage: TokenUsage,
617	    run_span: &tracing::Span,
618	) -> Option<AgentEvent> {
619	    let record_usage = |total: &TokenUsage| {
620	        run_span.record("gen_ai.usage.input_tokens", total.input_tokens as i64);
621	        run_span.record("gen_ai.usage.output_tokens", total.output_tokens as i64);
622	    };
623	    match ev {
624	        AgentEvent::RunStarted { .. } => None,
625	        AgentEvent::RunCompleted { usage } => {
626	            let mut total = parent_usage;
627	            total.add(usage);
628	            record_usage(&total);
629	            Some(AgentEvent::RunCompleted { usage: total })
630	        }
631	        AgentEvent::RunDeferred { calls, usage } => {
632	            let mut total = parent_usage;
633	            total.add(usage);
634	            record_usage(&total);
635	            run_span.record("paigasus.deferred_calls", calls.len() as i64);
636	            Some(AgentEvent::RunDeferred {
637	                calls,
638	                usage: total,
639	            })
640	        }
641	        AgentEvent::RunStopped { reason, usage } => {
642	            let mut total = parent_usage;
643	            total.add(usage);
644	            record_usage(&total);
645	            run_span.record("paigasus.stop_reason", reason.as_str());
646	            Some(AgentEvent::RunStopped {
647	                reason,
648	                usage: total,
649	            })
650	        }
651	        other => Some(other),
652	    }
653	}
