655	/// The `tool.execute` span of one tool call. `resumed` marks a resumed
656	/// deferred call (`paigasus.tool.resumed = true`); a normal call leaves that
657	/// field empty, so it is not exported.
658	pub(crate) fn tool_execute_span(
659	    parent: &tracing::Span,
660	    name: &str,
661	    resumed: bool,
662	) -> tracing::Span {
663	    let span = tracing::info_span!(
664	        target: "paigasus::core::agent",
665	        parent: parent,
666	        "tool.execute",
667	        otel.name = tracing::field::Empty,
668	        otel.kind = "internal",
669	        gen_ai.operation.name = "execute_tool",
670	        gen_ai.tool.name = %name,
671	        paigasus.tool.resumed = tracing::field::Empty,
672	        otel.status_code = tracing::field::Empty,
673	    );
674	    span.record("otel.name", format!("execute_tool {name}").as_str());
675	    if resumed {
676	        span.record("paigasus.tool.resumed", true);
677	    }
678	    span
679	}
