681	/// Invoke `tool` with `args`, fire `PostToolUse` on the raw JSON output, and
682	/// finalize the output. Redaction is the final transform. Call it inside the
683	/// call's `tool.execute` span: a tool error marks that span as `ERROR`.
684	pub(crate) async fn invoke_and_finalize<Ctx>(
685	    tool: &std::sync::Arc<dyn crate::Tool<Ctx>>,
686	    tool_ctx: &crate::ToolContext<Ctx>,
687	    args: serde_json::Value,
688	    interceptors: &crate::control::Interceptors<'_, Ctx>,
689	    redact_output: bool,
690	    secrets: &crate::redaction::SecretSet,
691	) -> Result<Vec<crate::ContentPart>, String>
692	where
693	    Ctx: Send + Sync + 'static,
694	{
695	    // Keep the tool's raw JSON output so the PostToolUse hook sees the
696	    // structured value, not a stringified form.
697	    let output_json = match tool.invoke(tool_ctx, args).await {
698	        Ok(output) => output.content,
699	        Err(e) => {
700	            tracing::Span::current().record("otel.status_code", "ERROR");
701	            return Err(e.to_string());
702	        }
703	    };
704	    // PostToolUse hook (ReplaceOutput / Deny→denial). The hook receives the
705	    // raw `serde_json::Value`; a `ReplaceOutput` value (or the original) is
706	    // rendered to content parts only at the end.
707	    let post = interceptors
708	        .fire(&crate::HookEvent::PostToolUse {
709	            tool: tool.name().to_owned(),
710	            output: output_json.clone(),
711	        })
712	        .await;
713	    if let Some(reason) = post.denied {
714	        return Err(format!("blocked by PostToolUse hook: {reason}"));
715	    }
716	    let final_json = post.replacement.unwrap_or(output_json);
717	    // Redaction is the FINAL transform — after user PostToolUse hooks — so a
718	    // hook cannot reintroduce an unredacted secret. Shared with the
719	    // durable-runner pipeline in `tool_exec.rs`.
720	    Ok(crate::finalize_tool_output(
721	        final_json,
722	        redact_output,
723	        secrets,
724	    ))
725	}
726	
727	/// Await `futures` in their order: all at once, or at most `limit` at a time.
728	pub(crate) async fn run_with_limit<F>(
729	    futures: impl Iterator<Item = F>,
730	    limit: Option<std::num::NonZeroUsize>,
731	) -> Vec<F::Output>
732	where
733	    F: std::future::Future,
734	{
735	    match limit {
736	        None => futures_util::future::join_all(futures).await,
737	        Some(n) => {
738	            use futures_util::stream::StreamExt as _;
739	            let collected: Vec<_> = futures.collect();
740	            futures_util::stream::iter(collected)
741	                .buffered(n.get())
742	                .collect()
743	                .await
744	        }
745	    }
746	}
