466	#[derive(Debug)]
467	pub struct SessionRecorder {
468	    events: Vec<SessionEvent>,
469	    current_agent: String,
470	    deferral_slot: Option<crate::DeferralSlot>,
471	    /// The call ids of the resumed calls (empty when the run is no resume).
472	    resume_call_ids: Vec<String>,
473	    /// The tool results that the agent emits before its first turn.
474	    resume_block: Vec<SessionEvent>,
