578	    /// and track the active agent from `RunStarted` / `AgentUpdated`.
579	    pub fn observe(&mut self, event: &AgentEvent) {
580	        match event {
581	            AgentEvent::RunStarted { agent } | AgentEvent::AgentUpdated { agent } => {
582	                self.current_agent = agent.clone();
583	            }
584	            AgentEvent::TurnStarted { .. } => {
