1147	/// One handoff response with a transfer call for each `(call_id, target)`.
1148	fn transfer_turn_with(calls: &[(&str, &str)]) -> Vec<ModelEvent> {
1149	    let mut turn: Vec<ModelEvent> = calls
1150	        .iter()
1151	        .map(|(call_id, target)| ModelEvent::ToolCallDelta {
1152	            call_id: (*call_id).to_owned(),
1153	            name: Some(format!("transfer_to_{target}")),
1154	            args_delta: "{}".to_owned(),
1155	        })
1156	        .collect();
1157	    turn.push(ModelEvent::Finish {
1158	        reason: FinishReason::ToolCalls,
1159	    });
1160	    turn
1161	}
