1163	/// `messages` has `count` calls `call_id`, and a result `call_id` follows
1164	/// each call directly. Returns the result texts in call order.
1165	fn results_after_each_call(messages: &[Item], call_id: &str, count: usize) -> Vec<String> {
1166	    let mut texts = Vec::new();
1167	    for (at, item) in messages.iter().enumerate() {
1168	        if !matches!(item, Item::ToolCall { call_id: id, .. } if id == call_id) {
1169	            continue;
1170	        }
1171	        match messages.get(at + 1) {
1172	            Some(Item::ToolResult {
1173	                call_id: id,
1174	                content,
1175	            }) if id == call_id => texts.push(text_of(content)),
1176	            other => panic!("{call_id} at {at} is not closed directly after: {other:?}"),
1177	        }
1178	    }
1179	    assert_eq!(texts.len(), count, "{messages:?}");
1180	    texts
1181	}
