    assert_eq!(
        events
            .iter()
            .filter(|e| matches!(e, AgentEvent::RunStarted { .. }))
            .count(),
        1
    );

    // Re-run through collect() to check final output attribution.
    let triage = member("triage", vec![transfer_turn("budgeting")]);
